+        if (indexCacheMiss != null) {
+            fillIndexCache(cacheFile, indexCacheMiss);
+            if (compoundFileOffset > 0L && indexCacheMiss.equals(headerBlobCacheByteRange) && footerBlobCacheByteRange.isEmpty() == false) {
